def test_monitor_summary_basic():
    e = [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}]
    assert monitor_summary({"g": e}, 1)["groups"] == 1


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate([
        {"flagged": True}, {"flagged": None}, {"flagged": False}
    ]) == 1 / 3
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_each_transcript_equally():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}] * 3,
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_uses_exactly_last_days_entries():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2], 5) == 3


def test_parse_log_flag_values_comments_and_whitespace():
    assert parse_transcript_log([
        "  # comment",
        "  x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
        "   ",
    ]) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


@pytest.mark.parametrize("lines", [
    ["x,1"],
    ["x,not-a-day,1"],
    ["x,1,true"],
])
def test_parse_log_rejects_invalid_lines_with_line_number(lines):
    with pytest.raises(ValueError, match="line 1"):
        parse_transcript_log(lines)


def test_parse_log_error_line_number_counts_skipped_lines():
    with pytest.raises(ValueError, match="line 3"):
        parse_transcript_log(["", "# ignored", "x,no,1"])


def test_dedupe_transcripts_keeps_last_duplicate_id():
    first = {"id": "x", "day": 1, "flagged": True}
    last = {"id": "x", "day": 3, "flagged": False}
    other = {"id": "y", "day": 2, "flagged": True}
    assert dedupe_transcripts([first, other, last]) == [other, last]


def test_daily_flag_counts_inclusive_range_and_empty_reverse_range():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": None},
        {"day": 3, "flagged": True},
        {"day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 3) == [1, 0, 1]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_uses_spec_rounding_and_nonempty_group_count():
    events = [{"day": 1, "flagged": True}] + [
        {"day": 2, "flagged": False} for _ in range(6)
    ]
    summary = monitor_summary({"active": events, "empty": []}, 1)
    assert summary == {"rate": 0.143, "recent": 0, "groups": 1}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_and_flag_rate_by_group_ordering():
    groups = {
        "z": [{"flagged": True}],
        "b": [{"flagged": False}],
        "a": [{"flagged": False}],
        "empty": [],
    }
    assert top_flagged_groups(groups, 3) == ["z", "a", "b"]
    assert flag_rate_by_group(groups) == {
        "a": 0.0, "b": 0.0, "empty": None, "z": 1.0
    }


def test_longest_flag_streak_requires_positive_counts():
    assert longest_flag_streak([1, 2, 0, -1, 3, 4]) == 2
    assert longest_flag_streak([]) == 0
